for v in p['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py') and v['role'] in ['candidate','control']
 text=Path(v['file']).read_text();t=ast.parse(text)
 assert config(t)==v['config']
 m=methods(t)
 assert set(m)==set(original_methods)
 for name in m:
  if name not in {'__init__','_pool','_pool_seven','_context_history_correction','forward'}:
   assert dump(m[name])==dump(original_methods[name]),name
 assert nn_calls(m['__init__'])==nn_calls(original_methods['__init__'])
 args=m['__init__'].args
 defaults={a.arg:ast.literal_eval(d) for a,d in zip(args.args[-len(args.defaults):],args.defaults) if isinstance(d,(ast.Constant,ast.Tuple,ast.List,ast.Dict))}
 for k,val in v['config'].items():
  expected=tuple(val) if isinstance(defaults.get(k),tuple) else val
  assert defaults[k]==expected,(v['name'],k,defaults.get(k),val)
 for n in ast.walk(t):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed_roots for a in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allowed_roots
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','exec','eval','compile','__import__','input'}
 # Normalize just the two declared defaults and literal CONFIG.
 n=copy.deepcopy(t)
 for node in ast.walk(n):
  if isinstance(node,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in node.targets):node.value=ast.Constant(None)
