   for a,d in zip(node.args.args[-len(node.args.defaults):],node.args.defaults):
    if a.arg=='summary_placement':d.value='NORMALIZED'
    if a.arg=='block_aux_adapter_context_grad':d.value=False
 normal.append(dump(n))
assert all(x==normal[0] for x in normal)
for ref in w['available_ancestor_sources']:
 assert hashlib.sha256(Path(ref['file']).read_bytes()).hexdigest()==ref['source_sha256'],ref['file']
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
assert hashlib.sha256(Path('/tmp/incumbent_original.py').read_bytes()).hexdigest()=='a2fe811c7ef287b2028ec5b5844ce47c40847af521e6d4e7dffd63834e2ed380'
