def evaluate(blocks,occupied,rest,weights,linear=False):
 width=len(weights[0])-len(rest);M=sum(occupied)
 safe=[b if ok else [0.0]*width for b,ok in zip(blocks,occupied)]
 total=[sum(b[k] for b in safe) for k in range(width)]
 f=(lambda x:x) if linear else math.tanh
 aggregate=[f(sum(a*b for a,b in zip(row,total+rest))) for row in weights]
 local=[sum(f(sum(a*b for a,b in zip(row,[M*x for x in b]+rest))) for b,ok in zip(safe,occupied) if ok)/max(M,1) for row in weights]
 return local,aggregate
for M in range(11):
 for rep in range(12):
  active=set(rng.sample(range(10),M));occupied=[j in active for j in range(10)]
  blocks=[[rng.uniform(-4,4) for _ in range(3)] for j in range(10)]
  rest=[rng.uniform(-2,2) for _ in range(2)]
  weights=[[rng.uniform(-2,2) for _ in range(5)] for _ in range(4)]
  loc,agg=evaluate(blocks,occupied,rest,weights)
  assert all(math.isfinite(x) and abs(x)<=1 for x in loc+agg)
  perm=list(range(10));rng.shuffle(perm)
  locp,aggp=evaluate([blocks[j] for j in perm],[occupied[j] for j in perm],rest,weights)
  for a,b in zip(loc+agg,locp+aggp):close(a,b)
  perturbed=[b if ok else [float('nan')]*3 for b,ok in zip(blocks,occupied)]
  loc2,agg2=evaluate(perturbed,occupied,rest,weights)
  for a,b in zip(loc+agg,loc2+agg2):close(a,b)
  ll,la=evaluate(blocks,occupied,rest,weights,linear=True)
  if M:
   for a,b in zip(ll,la):close(a,b)
   prototype=[rng.uniform(-2,2) for _ in range(3)]
   homogeneous=[prototype[:] for _ in range(10)]
   hl,ha=evaluate(homogeneous,occupied,rest,weights)
   for a,b in zip(hl,ha):close(a,b)
  else:assert loc==[0]*4
  if M==1:
   for a,b in zip(loc,agg):close(a,b)
