b,bb=evaluate([[1.],[1.]],[True,True],[0.3],[[1.,1.]])
close(aa[0],bb[0]);assert abs(a[0]-b[0])>0.1
for scale in [0.,1e-10,1e4]:
 loc,agg=evaluate([[scale],[-0.2*scale]],[True,True],[0.1],[[1.,1.]])
 assert all(math.isfinite(x) for x in loc+agg)
